import 'package:flutter/material.dart';
class LoadingView extends StatelessWidget { const LoadingView({super.key, this.label='Loading data…'}); final String label; @override Widget build(BuildContext context)=>Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children:[const CircularProgressIndicator(), const SizedBox(height:12), Text(label)]))); }
class ErrorView extends StatelessWidget { const ErrorView({super.key, required this.error, this.onRetry}); final Object error; final VoidCallback? onRetry; @override Widget build(BuildContext context)=>Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children:[const Icon(Icons.cloud_off_rounded,size:42), const SizedBox(height:10), Text(error.toString().replaceFirst('Exception: ',''), textAlign:TextAlign.center), if(onRetry!=null) ...[const SizedBox(height:12), FilledButton.icon(onPressed:onRetry, icon:const Icon(Icons.refresh), label:const Text('Retry'))]]))); }
class EmptyView extends StatelessWidget { const EmptyView({super.key, required this.message}); final String message; @override Widget build(BuildContext context)=>Center(child: Padding(padding:const EdgeInsets.all(24), child: Text(message,textAlign:TextAlign.center))); }
